using FluentValidation;using Microsoft.EntityFrameworkCore;using SchoolERP.Application.Abstractions;using SchoolERP.Application.Common.Extensions;using SchoolERP.Application.Common.Pagination;using SchoolERP.Application.Exceptions;using SchoolERP.Application.Features.Schools;using SchoolERP.Application.Security;using SchoolERP.Domain.Entities;using SchoolERP.Domain.Enums;namespace SchoolERP.Application.Features.SchoolCalendar;
public sealed class SchoolCalendarService(IApplicationDbContext db,ICurrentSchoolResolver current,IResourceScopeValidator scope,IValidator<CalendarEventRequest> validator,TimeProvider clock):ISchoolCalendarService{
 public async Task<PagedResult<CalendarEventDto>> ListAsync(GetCalendarEventsQuery r,CancellationToken ct=default){var sid=await current.ResolveAsync(ct);if(r.CampusId.HasValue)await Campus(r.CampusId.Value,sid,ct);if(r.AcademicYearId.HasValue)await Year(r.AcademicYearId.Value,sid,ct);var q=Visible(db.SchoolCalendarEvents.AsNoTracking().Where(x=>x.SchoolId==sid)).WhereIf(r.From.HasValue,x=>x.EndDate>=r.From).WhereIf(r.To.HasValue,x=>x.StartDate<=r.To).WhereIf(r.CampusId.HasValue,x=>x.CampusId==r.CampusId).WhereIf(r.AcademicYearId.HasValue,x=>x.AcademicYearId==r.AcademicYearId).WhereIf(r.Type.HasValue,x=>x.Type==r.Type).WhereIf(r.Status.HasValue,x=>x.Status==r.Status);if(!string.IsNullOrWhiteSpace(r.Search)){var t=r.Search.Trim().ToLower();q=q.Where(x=>x.Title.ToLower().Contains(t)||(x.Code!=null&&x.Code.ToLower().Contains(t))||(x.Location!=null&&x.Location.ToLower().Contains(t)));}q=q.OrderBy(x=>x.StartDate).ThenBy(x=>x.StartTime).ThenBy(x=>x.Title);return await q.Select(x=>new CalendarEventDto(x.Id,x.CampusId,x.Campus!=null?x.Campus.Name:null,x.AcademicYearId,x.AcademicYear!=null?x.AcademicYear.Name:null,x.Title,x.Code,x.Type,x.StartDate,x.EndDate,x.IsAllDay,x.StartTime,x.EndTime,x.IsWorkingDayOverride,x.ColorHex,x.Location,x.Description,x.Recurrence,x.RecurrenceEndDate,x.Status,x.PublishedAt,x.CancelledAt,x.ArchivedAt,x.CreatedAt,x.UpdatedAt)).ToPagedResultAsync(new(r.PageNumber,r.PageSize),ct);}
 public async Task<CalendarEventDto?> GetAsync(Guid id,CancellationToken ct=default){var sid=await current.ResolveAsync(ct);return await Visible(db.SchoolCalendarEvents.AsNoTracking().Where(x=>x.Id==id&&x.SchoolId==sid)).Select(x=>new CalendarEventDto(x.Id,x.CampusId,x.Campus!=null?x.Campus.Name:null,x.AcademicYearId,x.AcademicYear!=null?x.AcademicYear.Name:null,x.Title,x.Code,x.Type,x.StartDate,x.EndDate,x.IsAllDay,x.StartTime,x.EndTime,x.IsWorkingDayOverride,x.ColorHex,x.Location,x.Description,x.Recurrence,x.RecurrenceEndDate,x.Status,x.PublishedAt,x.CancelledAt,x.ArchivedAt,x.CreatedAt,x.UpdatedAt)).SingleOrDefaultAsync(ct);}
 public async Task<CalendarEventDto> CreateAsync(CalendarEventRequest r,CancellationToken ct=default){await validator.ValidateAndThrowAsync(r,ct);var sid=await current.ResolveAsync(ct);var school=await School(sid,ct);await Parents(r.CampusId,r.AcademicYearId,sid,ct);await Unique(sid,r.Code,null,ct);var x=SchoolCalendarEvent.Create(school.TenantId,sid,r.CampusId,r.AcademicYearId,r.Title,r.Code,r.Type,r.StartDate,r.EndDate,r.IsAllDay,r.StartTime,r.EndTime,r.IsWorkingDayOverride,r.ColorHex,r.Location,r.Description,r.Recurrence,r.RecurrenceEndDate,Now());db.SchoolCalendarEvents.Add(x);await db.SaveChangesAsync(ct);return(await GetAsync(x.Id,ct))!;}
 public async Task<CalendarEventDto?> UpdateAsync(Guid id,CalendarEventRequest r,CancellationToken ct=default){await validator.ValidateAndThrowAsync(r,ct);var x=await Write(id,ct);if(x is null)return null;if(x.CampusId!=r.CampusId||x.AcademicYearId!=r.AcademicYearId)throw new SchoolCalendarParentUnavailableException("SchoolCalendar.ScopeImmutable");await School(x.SchoolId,ct);await Unique(x.SchoolId,r.Code,id,ct);x.UpdateDetails(r.Title,r.Code,r.Type,r.StartDate,r.EndDate,r.IsAllDay,r.StartTime,r.EndTime,r.IsWorkingDayOverride,r.ColorHex,r.Location,r.Description,r.Recurrence,r.RecurrenceEndDate,Now());await db.SaveChangesAsync(ct);return await GetAsync(id,ct);}
 public Task<CalendarEventDto?> PublishAsync(Guid id,CancellationToken ct=default)=>Change(id,async x=>{var s=await db.Schools.AsNoTracking().SingleAsync(y=>y.Id==x.SchoolId,ct);if(s.Status!=SchoolStatus.Active)throw new SchoolCalendarParentUnavailableException("SchoolCalendar.SchoolMustBeActive");x.Publish(Now());},ct);public Task<CalendarEventDto?> CancelAsync(Guid id,CancellationToken ct=default)=>Change(id,x=>{x.Cancel(Now());return Task.CompletedTask;},ct);public Task<CalendarEventDto?> ArchiveAsync(Guid id,CancellationToken ct=default)=>Change(id,x=>{x.Archive(Now());return Task.CompletedTask;},ct);
 private async Task<CalendarEventDto?> Change(Guid id,Func<SchoolCalendarEvent,Task> action,CancellationToken ct){var x=await Write(id,ct);if(x is null)return null;await School(x.SchoolId,ct);await action(x);await db.SaveChangesAsync(ct);return await GetAsync(id,ct);}private IQueryable<SchoolCalendarEvent> Visible(IQueryable<SchoolCalendarEvent> q)=>scope.CampusId.HasValue?q.Where(x=>x.CampusId==null||x.CampusId==scope.CampusId):q;private async Task<SchoolCalendarEvent?> Write(Guid id,CancellationToken ct){var sid=await current.ResolveAsync(ct);return await Visible(db.SchoolCalendarEvents.Where(x=>x.Id==id&&x.SchoolId==sid)).SingleOrDefaultAsync(ct);}private async Task<School> School(Guid sid,CancellationToken ct){var s=await db.Schools.AsNoTracking().SingleAsync(x=>x.Id==sid,ct);if(s.Status is SchoolStatus.Suspended or SchoolStatus.Archived)throw new SchoolCalendarParentUnavailableException("SchoolCalendar.SchoolUnavailable");return s;}private async Task Parents(Guid? campus,Guid? year,Guid sid,CancellationToken ct){if(campus.HasValue)await Campus(campus.Value,sid,ct);if(year.HasValue)await Year(year.Value,sid,ct);}private async Task Campus(Guid id,Guid sid,CancellationToken ct){if(!scope.CanAccessCampus(sid,id)||!await db.Campuses.AsNoTracking().AnyAsync(x=>x.Id==id&&x.SchoolId==sid,ct))throw new ResourceNotFoundException("Campus");}private async Task Year(Guid id,Guid sid,CancellationToken ct){if(!await db.AcademicYears.AsNoTracking().AnyAsync(x=>x.Id==id&&x.SchoolId==sid,ct))throw new ResourceNotFoundException("Academic year");}private async Task Unique(Guid sid,string? code,Guid? except,CancellationToken ct){var c=SchoolCalendarEvent.NormalizeCode(code);if(c is not null&&await db.SchoolCalendarEvents.AsNoTracking().AnyAsync(x=>x.SchoolId==sid&&x.Code==c&&(!except.HasValue||x.Id!=except),ct))throw new SchoolCalendarCodeConflictException();}private DateTime Now()=>clock.GetUtcNow().UtcDateTime;}
